def inject_massive_edges(crg) -> int:
    """Inject all massive edges into CRG. Returns count added."""
    existing = {(e.src, e.label, e.dst) for e in crg.edges}
    added = 0
    for src, label, dst in MASSIVE_EDGES:
        if (src, label, dst) not in existing:
            crg.add_edge(src, label, dst)
            added += 1
    return added
